# Surah Hud (chapter 11) — part 11: ayat 101-110 (IDs 1574-1583)
SURAH = 11

ENTRIES = {
1574: (
"اور — ہم نے — ان — پر ظلم نہیں کیا — بلکہ — انہوں نے — خود — اپنی جان — پر ظلم کیا — پس — ان کے — وہ — معبود — جن کی عبادت — وہ — اللہ کے سوا کرتے تھے — انہیں — کوئی فائدہ — نہ دے سکے — جب — تمہارے رب کا حکم آیا — اور — ان — نے — ان میں — اضافہ نہیں کیا — مگر — تباہی",
"""۱۔ اللہ — ظلم — نہیں کرتا؛ معبود — کوئی فائدہ نہیں دے سکتے۔
۲۔ ’’وَمَا ظَلَمْنَاهُمْ وَلَٰكِن ظَلَمُوا أَنفُسَهُمْ فَمَا أَغْنَتْ عَنْهُمْ آلِهَتُهُمُ الَّتِي يَدْعُونَ مِن دُونِ اللَّهِ مِن شَيْءٍ لَّمَّا جَاءَ أَمْرُ رَبِّكَ وَمَا زَادُوهُمْ غَيْرَ تَتْبِيبٍ‘‘ — اور — ہم نے — ان — پر ظلم نہیں کیا — بلکہ — انہوں نے — خود — اپنی جان — پر ظلم کیا — پس — ان کے — وہ — معبود — جن کی عبادت — وہ — اللہ کے سوا کرتے تھے — انہیں — کوئی فائدہ — نہ دے سکے — جب — تمہارے رب کا حکم آیا — اور — ان — نے — ان میں — اضافہ نہیں کیا — مگر — تباہی — یعنی ہم — نے ان — پر — ظلم — نہیں کیا — بلکہ — وہ — خود — اپنے آپ — پر ظلم کرتے رہے — ان کے معبودوں — نے — کوئی فائدہ نہ دیا — جب تمہارے رب کا حکم آیا — اور انہوں نے — اضافہ نہیں کیا — مگر — تباہی۔
۳۔ عملی سبق: غیر اللہ کی عبادت — الٹا نقصان — دیتی ہے؛ صرف اللہ — کو — پکارو۔"""
),
1575: (
"اور — اسی طرح — تمہارے رب کی پکڑ — ہے — جب — وہ — کسی — بستی — کو پکڑتا ہے — اور — وہ — ظالم — ہوں — بے شک — اس کی پکڑ — دردناک — سخت — ہے",
"""۱۔ اللہ کی پکڑ — ظالموں — کے لیے — دردناک اور سخت۔
۲۔ ’’وَكَذَٰلِكَ أَخْذُ رَبِّكَ إِذَا أَخَذَ الْقُرَىٰ وَهِيَ ظَالِمَۃٌ إِنَّ أَخْذَهُ أَلِيمٌ شَدِيدٌ‘‘ — اور — اسی طرح — تمہارے رب کی پکڑ — ہے — جب — وہ — کسی — بستی — کو پکڑتا ہے — اور — وہ — ظالم — ہوں — بے شک — اس کی پکڑ — دردناک — سخت — ہے — یعنی اسی طرح — تمہارے رب کی پکڑ ہے — جب — وہ — کسی بستی — کو پکڑتا ہے — اور وہ ظالم ہوں — بے شک — اس کی پکڑ — دردناک — سخت — ہے۔
۳۔ عملی سبق: ظلم — عاقبت میں — دردناک پکڑ — کی طرف — لے جاتا ہے۔"""
),
1576: (
"بے شک — اس میں — نشانی — ہے — اس — کے لیے — جو — آخرت کے عذاب — سے — ڈرتا ہے — یہ — ایک دن — ہے — جس — کے لیے — سب — لوگ — جمع کیے جائیں گے — اور — یہ — ایک دن — ہے — جس — میں — سب دیکھیں گے",
"""۱۔ قیامت — کی نشانی — آخرت سے ڈرنے والوں — کے لیے۔
۲۔ ’’إِنَّ فِي ذَٰلِكَ لَآيَۃً لِّمَنْ خَافَ عَذَابَ الْآخِرَۃِ ذَٰلِكَ يَوْمٌ مَّجْمُوعٌ لَّهُ النَّاسُ وَذَٰلِكَ يَوْمٌ مَّشْهُودٌ‘‘ — بے شک — اس میں — نشانی — ہے — اس — کے لیے — جو — آخرت کے عذاب — سے — ڈرتا ہے — یہ — ایک دن — ہے — جس — کے لیے — سب — لوگ — جمع کیے جائیں گے — اور — یہ — ایک دن — ہے — جس — میں — سب دیکھیں گے — یعنی اس میں — آخرت کے — عذاب سے — ڈرنے والوں — کے لیے نشانی ہے — یہ — ایک دن ہے — جس میں — سب لوگ — جمع کیے جائیں گے — اور — یہ — ایک — دن — ہے — جس میں — سب — دیکھیں گے۔
۳۔ عملی سبق: آخرت — سے ڈرنے — والوں — کی آنکھیں — حق کو — دیکھتی ہیں۔"""
),
1577: (
"اور — ہم — اس — کو — ایک — مقرر — مدت — کے علاوہ — موخر — نہیں کرتے",
"""۱۔ قیامت — تاخیر — ایک مقررہ مدت — کی وجہ سے ہے۔
۲۔ ’’وَمَا نُؤَخِّرُهُ إِلَّا لِأَجَلٍ مَّعْدُودٍ‘‘ — اور — ہم — اس — کو — ایک — مقرر — مدت — کے علاوہ — موخر — نہیں کرتے — یعنی ہم اسے — ایک — مقرر — مدت — تک — موخر — نہیں کرتے — یعنی اس کی تاخیر صرف — ایک مقررہ مدت — کی وجہ سے ہے۔
۳۔ عملی سبق: قیامت — کا — وقت — اللہ جانتا ہے؛ ہماری فکر — تیار ہو — جانا — ہے۔"""
),
1578: (
"جس — دن — وہ — آ جائے — کوئی نفس — بات نہیں کرے گا — مگر — اس — کی اجازت سے — پس — ان میں سے — کوئی — بدبخت — ہے — اور — کوئی — خوش قسمت",
"""۱۔ قیامت میں — اجازت کے بغیر — بات — نہیں ہو گی — لوگ — بدبخت اور خوش قسمت۔
۲۔ ’’يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِهِ فَمِنْهُمْ شَقِيٌّ وَسَعِيدٌ‘‘ — جس — دن — وہ — آ جائے — کوئی نفس — بات نہیں کرے گا — مگر — اس — کی اجازت سے — پس — ان میں سے — کوئی — بدبخت — ہے — اور — کوئی — خوش قسمت — یعنی جس دن وہ آ جائے — کوئی نفس — بات — نہیں کرے گا — مگر اس کی اجازت سے — پس — ان میں سے — کوئی — بدبخت — ہے — اور — کوئی — خوش قسمت۔
۳۔ عملی سبق: اللہ کی اجازت کے بغیر — کوئی آواز — بھی نہیں — نکلے گی۔"""
),
1579: (
"پس — جو لوگ — بدبخت — ہوئے — وہ — آگ — میں ہیں — ان — کے لیے — اس — میں — کراہ — اور — ڈھینچ — ہے",
"""۱۔ بدبختوں کا ٹھکانا — آگ — کراہ اور ڈھینچ۔
۲۔ ’’فَأَمَّا الَّذِينَ شَقُوا فَفِي النَّارِ لَهُمْ فِيهَا زَفِيرٌ وَشَهِيقٌ‘‘ — پس — جو لوگ — بدبخت — ہوئے — وہ — آگ — میں ہیں — ان — کے لیے — اس — میں — کراہ — اور — ڈھینچ — ہے — یعنی پس — بدبخت — ہونے والے لوگ — آگ میں ہیں — ان کے لیے اس میں — کراہ اور — ڈھینچ — ہیں۔
۳۔ عملی سبق: بدبختی — آخرت میں — کراہ اور ڈھینچ — ہے؛ اجتناب — کرو۔"""
),
1580: (
"وہ — اس — میں ہمیشہ رہیں گے — جتنی مدت تک — آسمان اور زمین — قائم رہیں — مگر — جو — تیرے رب نے — چاہا — بے شک — تیرا — رب — جو — چاہتا ہے — کرتا ہے",
"""۱۔ بدبخت — آگ میں ہمیشہ — مگر — اللہ کی مشیت کے مطابق۔
۲۔ ’’خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ إِنَّ رَبَّكَ فَعَّالٌ لِّمَا يُرِيدُ‘‘ — وہ — اس — میں ہمیشہ رہیں گے — جتنی مدت تک — آسمان اور زمین — قائم رہیں — مگر — جو — تیرے رب نے — چاہا — بے شک — تیرا — رب — جو — چاہتا ہے — کرتا ہے — یعنی وہ — اس میں — ہمیشہ رہیں گے — جب تک آسمان اور زمین — قائم رہیں — مگر جو تمہارے رب نے چاہے؛ بے شک — تمہارا رب — جو — چاہتا ہے — کرتا ہے۔
۳۔ عملی سبق: آگ — کا — رہنا — اللہ — کی — مشیت — سے — ہے؛ ڈرنا — چاہیے۔"""
),
1581: (
"اور — جو لوگ — خوش قسمت — ہوئے — وہ — جنت — میں ہیں — ہمیشہ — اس — میں — رہیں گے — جتنی مدت تک — آسمان اور زمین — قائم رہیں — مگر — جو — تیرے رب — نے — چاہا — ایسا عطیہ — جو — ختم — نہیں",
"""۱۔ خوش قسمت — جنت — میں — ہمیشہ — ایسا عطیہ — جو — ختم نہیں۔
۲۔ ’’وَأَمَّا الَّذِينَ سُعِدُوا فَفِي الْجَنَّۃِ خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ عَطَاءً غَيْرَ مَجْذُوذٍ‘‘ — اور — جو لوگ — خوش قسمت — ہوئے — وہ — جنت — میں ہیں — ہمیشہ — اس — میں — رہیں گے — جتنی مدت تک — آسمان اور زمین — قائم رہیں — مگر — جو — تیرے رب — نے — چاہا — ایسا عطیہ — جو — ختم — نہیں — یعنی خوش قسمت — لوگ — جنت میں ہیں — ہمیشہ — اس — میں رہیں گے — جتنی مدت تک — آسمان اور زمین — قائم رہیں — مگر — جو تمہارے رب — نے — چاہے — یہ — ایسا عطیہ — ہے — جو — ختم — نہیں۔
۳۔ عملی سبق: جنت — اللہ — کا — عطیہ — ہے — جو — ختم — نہیں ہوتا۔"""
),
1582: (
"پس — آپ — ان کی — عبادتوں — میں — شک — میں — نہ ہوں — وہ — تو — صرف — ویسے عبادت — کر رہے ہیں — جیسے — ان — کے باپ دادا — اس سے پہلے — عبادت کرتے تھے — اور — بے شک — ہم — انہیں — ان — کا — پورا حصہ — پورا — پورا — دیں گے — بغیر کمی — کے",
"""۱۔ مشرکین — اپنے باپ دادا کی — پیروی میں ہیں؛ ان کا حصہ — پورا ملے گا۔
۲۔ ’’فَلَا تَكُ فِي مِرْيَۃٍ مِّمَّا يَعْبُدُ هَٰؤُلَاءِ مَا يَعْبُدُونَ إِلَّا كَمَا يَعْبُدُ آبَاؤُهُم مِّن قَبْلُ وَإِنَّا لَمُوَفُّوهُمْ نَصِيبَهُمْ غَيْرَ مَنقُوصٍ‘‘ — پس — آپ — ان کی — عبادتوں — میں — شک — میں — نہ ہوں — وہ — تو — صرف — ویسے عبادت — کر رہے ہیں — جیسے — ان — کے باپ دادا — اس سے پہلے — عبادت کرتے تھے — اور — بے شک — ہم — انہیں — ان — کا — پورا حصہ — پورا — پورا — دیں گے — بغیر کمی — کے — یعنی آپ — ان کی عبادت کے بارے میں شک — میں نہ ہوں — یہ لوگ — ویسی ہی عبادت کرتے ہیں — جیسے — ان کے باپ دادا کرتے تھے — اور — ہم — انہیں ان کا حصہ — پورا پورا دیں گے — بغیر کمی — کے۔
۳۔ عملی سبق: باپ دادا کی تقلید — راستہ نہیں؛ کسی کا حصہ — کم نہیں ہوگا۔"""
),
1583: (
"اور — ہم نے — موسیٰؑ — کو — کتاب — دی — تو — اس — میں — اختلاف — کر دیا گیا — اور — اگر — آپؐ — کے رب — کی طرف سے — ایک بات — پہلے — طے — نہ ہو گئی — ہوتی — تو — ان — کے درمیان — فیصلہ — ہو جاتا — اور — بے شک — وہ — اس — کے بارے میں — مشتبہ — شک — میں ہیں",
"""۱۔ تورات میں بھی — اختلاف — ہوا؛ اللہ کی حکمت — فیصلہ موخر۔
۲۔ ’’وَلَقَدْ آتَيْنَا مُوسَى الْكِتَابَ فَاخْتُلِفَ فِيهِ وَلَوْلَا كَلِمَۃٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِيَ بَيْنَهُمْ وَإِنَّهُمْ لَفِي شَكٍّ مِّنْهُ مُرِيبٍ‘‘ — اور — ہم نے — موسیٰؑ — کو — کتاب — دی — تو — اس — میں — اختلاف — کر دیا گیا — اور — اگر — آپؐ — کے رب — کی طرف سے — ایک بات — پہلے — طے — نہ ہو گئی — ہوتی — تو — ان — کے درمیان — فیصلہ — ہو جاتا — اور — بے شک — وہ — اس — کے بارے میں — مشتبہ — شک — میں ہیں — یعنی ہم نے — موسیٰؑ کو — کتاب دی — تو — اس — میں اختلاف — کر دیا گیا — اور — اگر — آپؐ کے رب کی طرف سے — ایک بات پہلے طے — نہ ہو گئی ہوتی — تو — ان کے درمیان — فیصلہ — ہو جاتا — اور بے شک — وہ — اس — کے بارے میں — مشتبہ — شک — میں ہیں۔
۳۔ عملی سبق: کتابوں میں اختلاف — انسانی — ہے؛ فیصلہ — اللہ — کرے گا۔"""
),
}
